 /* =========================================
   AJOBMART TRENDING IMAGE GALLERY
========================================= */

#ajTrendingProducts {
    display: flex;
    gap: 14px;
    overflow-x: auto;
    overflow-y: hidden;

    scroll-snap-type: x mandatory;
    scrollbar-width: none;

    padding: 8px 3px 16px;
}

#ajTrendingProducts::-webkit-scrollbar {
    display: none;
}

/* Remove traditional card appearance */
#ajTrendingProducts .aj-product-card {
    position: relative;

    flex: 0 0 calc((100% - 28px) / 3);
    min-width: 0;

    padding: 0;
    border: 0;
    border-radius: 16px;

    background: transparent;
    box-shadow: none;

    overflow: hidden;
    scroll-snap-align: start;
}

/* Image gallery tile */
#ajTrendingProducts .aj-product-image {
    position: relative;

    width: 100%;
    aspect-ratio: 4 / 5;

    padding: 0;
    overflow: hidden;

    border-radius: 16px;

    background:
        linear-gradient(
            145deg,
            #e8edff,
            #f9e7e9,
            #fce9cc
        );

    box-shadow:
        0 6px 16px rgba(20, 30, 60, .14);
}

/* Full image area */
#ajTrendingProducts .aj-product-details-link {
    display: flex;

    width: 100%;
    height: 100%;

    align-items: center;
    justify-content: center;
}

/* Make product images larger */
#ajTrendingProducts .aj-popular-product-img {
    width: 100%;
    height: 100%;

    object-fit: cover;

    transition: transform .4s ease;
}

/* Floating discount */
#ajTrendingProducts .aj-trending-discount-badge {
    position: absolute;

    top: 10px;
    left: 10px;

    z-index: 5;

    padding: 7px 11px;

    border-radius: 30px;

    background: linear-gradient(
        135deg,
        #ffdf73,
        #ff9e27
